<?php
declare(strict_types=1); require_once __DIR__.'/product_auth.php'; $pdo=db(); $errors=[]; $sku='';$name='';$description='';$price='';
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $sku=trim($_POST['sku']??'');$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$price=trim($_POST['price']??''); if($sku==='')$errors[]='SKU is required.'; if($name==='')$errors[]='Product name is required.'; if($price===''||!is_numeric($price)||(float)$price<0)$errors[]='Enter a valid price.'; if(!$errors){$s=$pdo->prepare('SELECT id FROM products WHERE sku=?');$s->execute([$sku]);if($s->fetch())$errors[]='This SKU already exists.';else{$s=$pdo->prepare('INSERT INTO products(sku,name,description,price) VALUES(?,?,?,?)');$s->execute([$sku,$name,$description?:null,number_format((float)$price,2,'.','')]);header('Location: products.php?success=Product%20created%20successfully.');exit;}}}
$pageTitle='Create Product'; require __DIR__.'/header.php'; ?><div class="card"><h1>Create Product</h1><?php foreach($errors as $x): ?><div class="alert error"><?= e($x) ?></div><?php endforeach; ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>SKU ID<input name="sku" maxlength="100" required value="<?= e($sku) ?>"></label><label>Product Name<input name="name" maxlength="255" required value="<?= e($name) ?>"></label><label>Price<input type="number" name="price" min="0" step="0.01" required value="<?= e($price) ?>"></label><label>Description<textarea name="description" rows="5"><?= e($description) ?></textarea></label><button type="submit">Create Product</button><a class="button secondary" href="products.php">Cancel</a></form></div><?php require __DIR__.'/footer.php'; ?>
